package spell

import (
	"reflect"
	"strings"
	"testing"

	"github.com/egladman/magus/internal/interp/bindings/gen/decode"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// The signature table is generated by parsing Contract's source, so a field added here
// without regenerating leaves the check blind to it. This holds the two to one list.
func TestContractFuncsMatchTheContract(t *testing.T) {
	rt := reflect.TypeFor[Contract]()
	require.Len(t, decode.ContractFuncs, rt.NumField(), "decode.ContractFuncs is stale; regenerate with magus run types-generate")
	for i := range rt.NumField() {
		f := rt.Field(i)
		name, opts, _ := strings.Cut(f.Tag.Get("mgs"), ",")
		got := decode.ContractFuncs[i]
		// Returns is the generator's own reading of the source, which the tag does not carry.
		assert.Equal(t, decode.ContractFunc{
			Name:     name,
			Field:    f.Name,
			Returns:  got.Returns,
			Required: strings.Contains(opts, "required"),
		}, got, "Contract.%s", f.Name)
	}
}

// Only mgs_getName is required: every other function is one a spell may leave out, and
// NameFunc is what Resolve tests for.
func TestContractRequiresOnlyTheName(t *testing.T) {
	var required []string
	for _, fn := range decode.ContractFuncs {
		if fn.Required {
			required = append(required, fn.Name)
		}
	}
	assert.Equal(t, []string{NameFunc}, required)
}
